"use client";
import { useEffect, useRef } from "react";
import { useGameStore } from "@/store/useGameStore";

export default function GameCanvas() {
  const gameRef = useRef<any>(null);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    
    // 비동기로 Phaser 로드 (SSR 오류 방지)
    const initPhaser = async () => {
      const Phaser = await import("phaser");

      if (gameRef.current) return;

    const config: Phaser.Types.Core.GameConfig = {
      type: Phaser.AUTO,
      parent: "game-container",
      backgroundColor: "#000000",
      scale: {
        mode: Phaser.Scale.RESIZE, // 화면 크기에 맞게 캔버스 크기 변경
        width: '100%',
        height: '100%',
        autoCenter: Phaser.Scale.CENTER_BOTH,
      },
      render: {
        pixelArt: true, // 도트가 깨지지 않고 선명하게 출력됨
        antialias: false,
      },
      physics: {
        default: "arcade",
        arcade: { debug: false },
      },
      scene: {
        preload: function (this: Phaser.Scene) {
          // 배경 이미지
          this.load.image("bg_001", "/assets/background_001.png");
          this.load.image("bg_002", "/assets/background_002.png");
          this.load.image("bg_003", "/assets/background_003.png");
          // 오피스 이미지
          this.load.image("ofc_001", "/assets/office_001.png");
          this.load.image("ofc_002", "/assets/office_002.png");
          this.load.image("ofc_003", "/assets/office_003.png");
          // 책상
          this.load.image("desks", "/assets/desks_001.png");
        },
        create: function (this: Phaser.Scene) {
          const { width, height } = this.scale;

          const hour = new Date().getHours();
          let bgKey = "bg_001";
          let ofcKey = "ofc_001";

          if (hour >= 8 && hour < 17) {
            bgKey = "bg_001";
            ofcKey = "ofc_001";
          } else if ((hour >= 6 && hour < 8) || (hour >= 17 && hour < 19)) {
            bgKey = "bg_002";
            ofcKey = "ofc_002";
          } else {
            bgKey = "bg_003";
            ofcKey = "ofc_003";
          }

          const container = this.add.container(width / 2, height / 2);
          
          const bg = this.add.image(0, 0, bgKey);
          const ofc = this.add.image(0, 0, ofcKey);
          container.add([bg, ofc]);

          // 책상 5개 배치 (원근감에 맞게 Y, X 조절)
          const deskPositions = [
            { x: -300, y: 180 },
            { x: -150, y: 250 },
            { x: 0, y: 180 },
            { x: 150, y: 250 },
            { x: 300, y: 180 },
          ];

          deskPositions.forEach(pos => {
            const desk = this.add.image(pos.x, pos.y, "desks");
            container.add(desk);
          });
          
          const resizeAll = () => {
            // 원본 배경 크기를 기준으로 전체 스케일링
            const scaleX = this.scale.width / bg.width;
            const scaleY = this.scale.height / bg.height;
            const scale = Math.max(scaleX, scaleY); 
            container.setScale(scale);
          };

          resizeAll();

          this.scale.on('resize', (gameSize: Phaser.Structs.Size) => {
            container.setPosition(gameSize.width / 2, gameSize.height / 2);
            resizeAll();
          });
        },
      },
    };

    };

    initPhaser();

    return () => {
      gameRef.current?.destroy(true);
      gameRef.current = null;
    };
  }, []);

  return <div id="game-container" className="fixed inset-0 w-full h-full touch-none" />;
}
